// Llamada de ejemplo para probar el sub-workflow con "Execute workflow".
const ahora = Date.now();
return [{ json: {
  flujo: 'B', paso: 'prueba_manual', proveedor: 'groq', ejecucion: $execution.id,
  inicio: new Date(ahora - 900).toISOString(), fin: new Date(ahora).toISOString(),
  prompt: 'Prueba desde n8n: ¿cómo está el aire en Ate?',
  respuesta: { model: 'llama-3.3-70b-versatile',
    choices: [{ message: { content: 'Respuesta de prueba' } }],
    usage: { prompt_tokens: 25, completion_tokens: 5, total_tokens: 30 } }
} }];

// ============================================================================
// Nodo Code "Armar span OTLP" (modo: Run Once for Each Item)
// Sub-workflow "Langfuse - Registrar llamada"
//
// Recibe UNA llamada (a Groq, Gemini o Telegram) y la convierte en un span
// OpenTelemetry que Langfuse entiende. El nodo siguiente lo manda por HTTP.
//
// Entrada esperada ($json):
//   flujo       'A' | 'B' | 'HU01' | 'HU02'
//   paso        'intencion' | 'respuesta' | 'analisis_anomalia' | 'embedding_consulta' | 'telegram_envio' ...
//   proveedor   'groq' | 'gemini' | 'telegram'
//   tipo        'generation' (defecto) | 'embedding' | 'span'
//   ejecucion   $execution.id del flujo que llama
//   inicio      ISO, justo antes de llamar a la API
//   fin         ISO, justo después (si falta, ahora)
//   prompt      texto u objeto que se mandó (opcional)
//   respuesta   respuesta cruda de la API (opcional)
//   error       mensaje de error si la llamada falló (opcional)
//   modelo      nombre del modelo, si la respuesta no lo trae (opcional)
//   es_fallback true si es Gemini respondiendo porque Groq falló (opcional)
//   extra       objeto con metadatos adicionales (opcional)
// ============================================================================

// <<< CAMBIA ESTO por la URL de tu Langfuse (sin / al final) >>>
const LANGFUSE_HOST = 'https://us.cloud.langfuse.com';
const ENTORNO = 'produccion';
const MAX_TEXTO = 20000; // recorta prompts/respuestas muy largos

const e = $json;

// ---------- utilidades ----------
const hex = (n) => {
  let s = '';
  for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 16).toString(16);
  return s;
};
const nanos = (iso) => {
  const ms = Date.parse(iso);
  return String(Number.isFinite(ms) ? ms : Date.now()) + '000000';
};
const texto = (v) => {
  if (v === null || v === undefined) return '';
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return s.length > MAX_TEXTO ? s.slice(0, MAX_TEXTO) + '…[recortado]' : s;
};
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);

// ---------- leer la respuesta según el proveedor ----------
const r = e.respuesta && typeof e.respuesta === 'object' ? e.respuesta : {};
let modelo = e.modelo || null;
let salida = null;
const uso = {};

if (e.proveedor === 'groq') {
  // API compatible con OpenAI: choices[0].message.content y usage.*_tokens
  modelo = modelo || r.model || null;
  salida = r.choices?.[0]?.message?.content ?? null;
  if (num(r.usage?.prompt_tokens) !== null) uso.input = r.usage.prompt_tokens;
  if (num(r.usage?.completion_tokens) !== null) uso.output = r.usage.completion_tokens;
} else if (e.proveedor === 'gemini') {
  // generateContent: candidates[0].content.parts[].text y usageMetadata
  // embedContent: embedding.values (sin conteo de tokens)
  modelo = modelo || r.modelVersion || null;
  if (Array.isArray(r.embedding?.values)) {
    salida = `vector(${r.embedding.values.length})`;
  } else {
    const partes = r.candidates?.[0]?.content?.parts;
    salida = Array.isArray(partes) ? partes.map((p) => p.text ?? '').join('') : null;
  }
  const u = r.usageMetadata || {};
  if (num(u.promptTokenCount) !== null) uso.input = u.promptTokenCount;
  if (num(u.candidatesTokenCount) !== null) uso.output = u.candidatesTokenCount;
  // los tokens de "razonamiento" de Gemini 2.5 van aparte (cada token en un solo grupo)
  if (num(u.thoughtsTokenCount) !== null && u.thoughtsTokenCount > 0) uso.output_reasoning = u.thoughtsTokenCount;
} else if (e.proveedor === 'telegram') {
  salida = r.ok === undefined ? null : { ok: r.ok, description: r.description ?? null };
}

// ¿falló? (error explícito o respuesta de Telegram con ok:false)
let error = e.error ? texto(e.error) : null;
if (!error && e.proveedor === 'telegram' && r.ok === false) error = texto(r.description || 'Telegram ok:false');
if (!error && r.error) error = texto(r.error.message || r.error);

// ---------- atributos del span ----------
const tipo = e.tipo || (e.proveedor === 'telegram' ? 'span' : 'generation');
const flujo = String(e.flujo || 'desconocido');
const paso = String(e.paso || 'llamada');
const proveedor = String(e.proveedor || 'desconocido');
const ejecucion = String(e.ejecucion ?? '');

const attrs = [];
const add = (k, v) => {
  if (v === null || v === undefined || v === '') return;
  attrs.push({ key: k, value: { stringValue: String(v) } });
};
const addArray = (k, arr) =>
  attrs.push({ key: k, value: { arrayValue: { values: arr.map((x) => ({ stringValue: String(x) })) } } });

add('langfuse.trace.name', `Flujo ${flujo}`);
addArray('langfuse.trace.tags', [`flujo:${flujo}`, `proveedor:${proveedor}`, `paso:${paso}`]);
add('langfuse.trace.metadata.n8n_execution', ejecucion);
add('langfuse.environment', ENTORNO);
add('langfuse.observation.type', tipo);
add('langfuse.observation.model.name', modelo);
add('langfuse.observation.input', e.prompt === undefined ? null : texto(e.prompt));
add('langfuse.observation.output', salida === null ? null : texto(salida));
if (Object.keys(uso).length) add('langfuse.observation.usage_details', JSON.stringify(uso));
add('langfuse.observation.level', error ? 'ERROR' : 'DEFAULT');
add('langfuse.observation.status_message', error);
add('langfuse.observation.metadata.proveedor', proveedor);
add('langfuse.observation.metadata.paso', paso);
add('langfuse.observation.metadata.flujo', flujo);
add('langfuse.observation.metadata.es_fallback', e.es_fallback ? 'true' : 'false');
for (const [k, v] of Object.entries(e.extra || {})) add(`langfuse.observation.metadata.${k}`, texto(v));

// Una traza por ejecución de n8n: el mismo traceId agrupa intención + respuesta.
// (32 caracteres hex; la letra del flujo + el id numérico de la ejecución)
const prefijo = { A: 'a', B: 'b', HU01: 'c', HU02: 'd' }[flujo] || 'e';
const traceId = /^\d+$/.test(ejecucion)
  ? (prefijo + '0' + ejecucion).padStart(32, '0').slice(-32)
  : hex(32);

const inicio = e.inicio || new Date().toISOString();
const fin = e.fin || new Date().toISOString();

const span = {
  traceId,
  spanId: hex(16),
  name: `${proveedor}-${paso}`,
  kind: 1,
  startTimeUnixNano: nanos(inicio),
  endTimeUnixNano: nanos(fin),
  attributes: attrs,
  status: error ? { code: 2, message: error } : { code: 1 },
};

return {
  json: {
    url: `${LANGFUSE_HOST}/api/public/otel/v1/traces`,
    otlp: {
      resourceSpans: [
        {
          resource: { attributes: [{ key: 'service.name', value: { stringValue: 'ecopredict-n8n' } }] },
          scopeSpans: [{ scope: { name: 'ecopredict-langfuse' }, spans: [span] }],
        },
      ],
    },
    resumen: { traceId, nombre: span.name, modelo, uso, error, latencia_ms: Date.parse(fin) - Date.parse(inicio) },
  },
};
